import json
from itertools import permutations

def solve_puzzle():
    houses = [0, 1, 2]  # 0->house1, 1->house2, 2->house3

    names = ['Arnold', 'Eric', 'Peter']
    musics = ['pop', 'rock', 'classical']
    children = ['Fred', 'Meredith', 'Bella']
    books = ['mystery', 'romance', 'science fiction']

    def invert_mapping(pos_map, items):
        inv = [None] * len(houses)
        for item in items:
            inv[pos_map[item]] = item
        return inv

    # Clue 2: Peter is in the first house (index 0)
    for arnold_pos, eric_pos in permutations([1, 2], 2):
        name_pos = {
            'Peter': 0,
            'Arnold': arnold_pos,
            'Eric': eric_pos
        }

        # Try all permutations for books
        for book_perm in permutations(houses):
            book_pos = {
                'mystery': book_perm[0],
                'romance': book_perm[1],
                'science fiction': book_perm[2]
            }

            # Clue 5: Eric is the person who loves mystery books.
            if name_pos['Eric'] != book_pos['mystery']:
                continue

            # Try all permutations for music
            for music_perm in permutations(houses):
                music_pos = {
                    'pop': music_perm[0],
                    'rock': music_perm[1],
                    'classical': music_perm[2]
                }

                # Clue 3: The person who loves mystery books is the person who loves classical music.
                if music_pos['classical'] != book_pos['mystery']:
                    continue

                # Clue 6: rock is somewhere to the right of romance
                if not (music_pos['rock'] > book_pos['romance']):
                    continue

                # Try all permutations for children
                for child_perm in permutations(houses):
                    child_pos = {
                        'Fred': child_perm[0],
                        'Meredith': child_perm[1],
                        'Bella': child_perm[2]
                    }

                    # Clue 1: Fred is directly left of mystery
                    if not (child_pos['Fred'] + 1 == book_pos['mystery']):
                        continue

                    # Clue 4: science fiction books with Meredith
                    if not (book_pos['science fiction'] == child_pos['Meredith']):
                        continue

                    # Construct solution rows
                    names_by_pos = invert_mapping(name_pos, names)
                    musics_by_pos = invert_mapping(music_pos, musics)
                    children_by_pos = invert_mapping(child_pos, children)
                    books_by_pos = invert_mapping(book_pos, books)

                    rows = []
                    for i in range(3):
                        rows.append([
                            str(i + 1),
                            names_by_pos[i],
                            musics_by_pos[i],
                            children_by_pos[i],
                            books_by_pos[i]
                        ])

                    header = ["House", "name", "favorite music genres", "child", "favorite book genres"]
                    solution = {
                        "solution": {
                            "header": header,
                            "rows": rows
                        }
                    }
                    return solution

    raise ValueError("No solution found")

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
